class Solution {
    public int countHomogenous(String text){
        final int MOD=1_000_000_007;
        long answer=0,run=0;
        for(int i=0;i<text.length();i++){
            run=i>0&&text.charAt(i)==text.charAt(i-1)?run+1:1;
            answer=(answer+run)%MOD;
        }
        return (int)answer;
    }
}

code.kotlin:
class Solution {
    fun countHomogenous(text:String):Int{
        val mod=1_000_000_007L;
        var answer=0L;
        var run=0L;
        for(i in text.indices){
            run=if(i>0&&text[i]==text[i-1])run+1 else 1;
            answer=(answer+run)%mod
        };
        return answer.toInt()
    }
}

code.cpp:
class Solution {
    public: int countHomogenous(string text){
        const int MOD=1000000007;
        long long answer=0,run=0;
        for(int i=0;i<(int)text.size();++i){
            run=i&&text[i]==text[i-1]?run+1:1;
            answer=(answer+run)%MOD;
        }
        return answer;
    }
};
